os.makedirs("0", exist_ok=True)
os.makedirs("system", exist_ok=True)
os.makedirs("constant", exist_ok=True)

# Physical constants and Initial Conditions
# Air approx: R=287, Cp=1005, Cv=718, gamma=1.4
R = 287.0
Cp = 1005.0
Cv = Cp - R
gamma = 1.4

U_inlet_mag = 1.3
T_inlet = 1.0
rho_inlet = 1.0

p_inlet = rho_inlet * R * T_inlet
e_inlet = Cv * T_inlet
E_inlet = e_inlet + 0.5 * U_inlet_mag**2
rhoU_inlet = rho_inlet * U_inlet_mag
rhoE_inlet = rho_inlet * E_inlet

